class Solution {
    public boolean findGameWinner(int n) {
        if (n == 1) return false;
        int a = 0, b = 1; // grundy of order(1), order(2)
        for (int i = 3; i <= n; i++) {
            int c = (a + 1) ^ (b + 1);
            a = b;
            b = c;
        }
        return b != 0;
    }
}
